    $meta.append($sheetWrap);
    if (state && state.sourceFileName) {
      $meta.append(
        $("<span/>").text(" · "),
        $("<span/>").addClass("ujg-esi-file-name ujg-esi-meta-file").text(String(state.sourceFileName))
      );
    }
    $header.append($meta);
